function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || !Array.isArray(grid[0]) || grid[0].length < 1) return 'grid needs at least one row and one column.';
  const n = grid[0].length;
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'Every row of grid must have the same length.';
  if (grid.length * n > 100000) return 'grid has at most 10^5 cells.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 1000))) return 'Each value is an integer between 1 and 1000.';
  return null;
}

