function maxTrailingZeros(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const power = (value, prime) => {
    let count = 0;
    while (value % prime === 0) {
      value /= prime;
      count++;
    }
    return count;
  };
  // rowTwos[i][j]: factors of 2 in grid[i][0..j-1]; colTwos[i][j]: factors of 2 in grid[0..i-1][j].
  const rowTwos = Array.from({ length: m }, () => new Array(n + 1).fill(0));
  const rowFives = Array.from({ length: m }, () => new Array(n + 1).fill(0));
  const colTwos = Array.from({ length: m + 1 }, () => new Array(n).fill(0));
  const colFives = Array.from({ length: m + 1 }, () => new Array(n).fill(0));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      const twos = power(grid[i][j], 2);
      const fives = power(grid[i][j], 5);
      rowTwos[i][j + 1] = rowTwos[i][j] + twos;
      rowFives[i][j + 1] = rowFives[i][j] + fives;
      colTwos[i + 1][j] = colTwos[i][j] + twos;
      colFives[i + 1][j] = colFives[i][j] + fives;
    }
  }

  let best = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      // Horizontal arms include the corner cell; vertical arms leave it out.
      const leftTwos = rowTwos[i][j + 1];
      const leftFives = rowFives[i][j + 1];
      const rightTwos = rowTwos[i][n] - rowTwos[i][j];
      const rightFives = rowFives[i][n] - rowFives[i][j];
      const upTwos = colTwos[i][j];
      const upFives = colFives[i][j];
      const downTwos = colTwos[m][j] - colTwos[i + 1][j];
      const downFives = colFives[m][j] - colFives[i + 1][j];
      best = Math.max(best, Math.min(leftTwos + upTwos, leftFives + upFives));
      best = Math.max(best, Math.min(leftTwos + downTwos, leftFives + downFives));
      best = Math.max(best, Math.min(rightTwos + upTwos, rightFives + upFives));
      best = Math.max(best, Math.min(rightTwos + downTwos, rightFives + downFives));
    }
  }
  return best;
}

