function maxTrailingZeros(grid) {
  // Grow every horizontal arm and then every vertical arm from every corner, multiplying exactly with BigInt.
  const m = grid.length, n = grid[0].length;
  const zeros = (big) => { const text = big.toString(); let k = 0; while (text[text.length - 1 - k] === '0') k++; return k; };
  let best = 0;
  for (let r = 0; r < m; r++)
    for (let c = 0; c < n; c++)
      for (const dc of [-1, 1]) {
        let horizontal = 1n;
        for (let col = c; col >= 0 && col < n; col += dc) {
          horizontal *= BigInt(grid[r][col]);
          best = Math.max(best, zeros(horizontal));
          for (const dr of [-1, 1]) {
            let product = horizontal;
            for (let row = r + dr; row >= 0 && row < m; row += dr) {
              product *= BigInt(grid[row][c]);
              best = Math.max(best, zeros(product));
            }
          }
        }
      }
  return best;
}

