function generate(rand, size) {
  let m, n;
  if (size === 'large') {
    const shape = rand();
    if (shape < 0.4) { m = 100; n = 100; }
    else if (shape < 0.55) { m = 1; n = 100; }
    else if (shape < 0.7) { m = 100; n = 1; }
    else { m = 1 + Math.floor(rand() * 100); n = 1 + Math.floor(rand() * 100); }
  } else {
    m = 1 + Math.floor(rand() * 5);
    n = 1 + Math.floor(rand() * 5);
  }
  // Values rich in 2s and 5s make the counts interesting; some plain values keep them honest.
  const pool = [1, 2, 4, 5, 8, 10, 16, 20, 25, 40, 50, 64, 100, 125, 250, 256, 500, 512, 625, 1000];
  const pick = () => rand() < 0.5 ? pool[Math.floor(rand() * pool.length)] : 1 + Math.floor(rand() * 1000);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, pick));
  return [grid];
}
